@charset "UTF-8";
/* Reset e base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.custom-table-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  max-width: 100%;
  background: #f8f9fa;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* Header */
.header-info {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 1.5rem 2rem;
  border-radius: 12px;
  margin: 1rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-title {
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.4;
  text-align: center;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

.header-title .highlight {
  background: rgba(255, 255, 255, 0.2);
  padding: 0.2rem 0.5rem;
  border-radius: 6px;
  font-weight: 700;
  margin: 0 0.2rem;
}

/* Indicatore di progresso */
.progress-indicator {
  background: white;
  padding: 1rem 2rem;
  margin: 0 1rem 1rem;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  border: 1px solid #e9ecef;
  font-size: 0.95rem;
  font-weight: 500;
}

.progress-indicator span {
  white-space: nowrap;
}

.validation-summary {
  color: #dc3545;
  font-weight: 600;
  background: #f8d7da;
  padding: 0.5rem 1rem;
  border-radius: 6px;
  border: 1px solid #f5c6cb;
}

/* Contenitore tabella */
.table-container {
  flex: 1;
  margin: 0 1rem;
  background: white;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  border: 1px solid #e9ecef;
}

/* Tabella */
.detail-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.detail-table th {
  background: #f8f9fa;
  padding: 1rem 1.5rem;
  text-align: left;
  font-weight: 600;
  color: #495057;
  border-bottom: 2px solid #dee2e6;
  width: 30%;
  vertical-align: middle;
  position: relative;
}

.detail-table td {
  padding: 1rem 1.5rem;
  border-bottom: 1px solid #e9ecef;
  vertical-align: middle;
}

.detail-table tr:hover {
  background: #f8f9fa;
}

.detail-table tr.error-row {
  background: #fff5f5;
  border-left: 4px solid #dc3545;
}

.detail-table tr.error-row th {
  background: #fff5f5;
  color: #dc3545;
}

/* Indicatore campo obbligatorio */
.required-indicator {
  color: #dc3545;
  font-weight: bold;
  margin-left: 0.3rem;
  font-size: 1.1rem;
}

/* Textarea per note */
textarea {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid #e9ecef;
  border-radius: 6px;
  font-family: inherit;
  font-size: 0.9rem;
  resize: vertical;
  min-height: 60px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

textarea:focus {
  outline: none;
  border-color: #007bff;
  box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.1);
}

textarea.error {
  border-color: #dc3545;
  background: #fff5f5;
}

textarea.error:focus {
  border-color: #dc3545;
  box-shadow: 0 0 0 3px rgba(220, 53, 69, 0.1);
}

/* Sistema di rating a stelle */
.star-rating {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.5rem 0;
}

.star-rating.error {
  background: #fff5f5;
  border-radius: 6px;
  padding: 0.5rem;
  border: 2px solid #dc3545;
}

.star {
  font-size: 1.8rem;
  color: #ffc107;
  cursor: pointer;
  transition: all 0.2s ease;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  user-select: none;
}

.star:hover {
  transform: scale(1.1);
  filter: brightness(1.2);
}

.star.inactive {
  color: #dee2e6;
  text-shadow: none;
}

.star.hovered {
  transform: scale(1.2);
  filter: brightness(1.3) drop-shadow(0 2px 4px rgba(255, 193, 7, 0.4));
}

.error-text {
  color: #dc3545;
  font-size: 0.8rem;
  margin-left: 0.5rem;
  font-weight: 500;
}

/* Pulsante di invio */
.button-invia {
  background: linear-gradient(135deg, #28a745 0%, #20c997 100%);
  color: white;
  border: none;
  padding: 1rem 2rem;
  font-size: 1.1rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  margin: 1rem;
  box-shadow: 0 4px 12px rgba(40, 167, 69, 0.3);
  transition: all 0.2s ease;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.button-invia:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(40, 167, 69, 0.4);
}

.button-invia:active {
  transform: translateY(0);
}

.button-invia:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.button-invia.error {
  background: linear-gradient(135deg, #dc3545 0%, #c82333 100%);
  box-shadow: 0 4px 12px rgba(220, 53, 69, 0.3);
}

.button-invia.error:hover:not(:disabled) {
  box-shadow: 0 6px 16px rgba(220, 53, 69, 0.4);
}

/* Animazioni */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.detail-table tr {
  animation: fadeIn 0.3s ease forwards;
}

.detail-table tr:nth-child(even) {
  animation-delay: 0.05s;
}

.detail-table tr:nth-child(odd) {
  animation-delay: 0.1s;
}

/* Responsività */
@media (max-width: 768px) {
  .header-info {
    margin: 0.5rem;
    padding: 1rem;
  }
  .header-title {
    font-size: 1.2rem;
  }
  .progress-indicator {
    flex-direction: column;
    gap: 0.5rem;
    margin: 0 0.5rem 0.5rem;
    padding: 1rem;
  }
  .table-container {
    margin: 0 0.5rem;
  }
  .detail-table th,
  .detail-table td {
    padding: 0.75rem 1rem;
  }
  .detail-table th {
    width: 35%;
  }
  .button-invia {
    margin: 0.5rem;
  }
  .star {
    font-size: 1.5rem;
  }
}
@media (max-width: 480px) {
  .header-title {
    font-size: 1rem;
  }
  .detail-table {
    font-size: 0.85rem;
  }
  .detail-table th,
  .detail-table td {
    padding: 0.5rem 0.75rem;
  }
  .progress-indicator {
    font-size: 0.85rem;
  }
}
/* Miglioramenti per l'accessibilità */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
/* Focus per navigazione con tastiera */
.star:focus,
textarea:focus,
.button-invia:focus {
  outline: 2px solid #007bff;
  outline-offset: 2px;
}

/* Stato di caricamento */
.button-invia:disabled {
  position: relative;
  overflow: hidden;
}

.button-invia:disabled::after {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  animation: loading 1.5s infinite;
}

@keyframes loading {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}
/* Scrollbar personalizzata */
.table-container::-webkit-scrollbar {
  width: 8px;
}

.table-container::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb {
  background: #c1c1c1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb:hover {
  background: #a8a8a8;
}

