  }

  .header-title {
    font-size: 1.2rem;
  }

  .progress-indicator {
    flex-direction: column;
    gap: 0.5rem;
    margin: 0 0.5rem 0.5rem;
    padding: 1rem;
  }

  .table-container {
    margin: 0 0.5rem;
  }

  .detail-table th,
  .detail-table td {
    padding: 0.75rem 1rem;
  }

  .detail-table th {
    width: 35%;
  }

  .button-invia {
    margin: 0.5rem;
  }

  .star {
    font-size: 1.5rem;
  }
}

@media (max-width: 480px) {
  .header-title {
    font-size: 1rem;
  }

  .detail-table {
    font-size: 0.85rem;
  }

  .detail-table th,
  .detail-table td {
    padding: 0.5rem 0.75rem;
  }

  .progress-indicator {
    font-size: 0.85rem;
  }
}

/* Miglioramenti per l'accessibilità */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Focus per navigazione con tastiera */
.star:focus,
textarea:focus,
.button-invia:focus {
  outline: 2px solid #007bff;
  outline-offset: 2px;
}

/* Stato di caricamento */
.button-invia:disabled {
  position: relative;
  overflow: hidden;
}

.button-invia:disabled::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  animation: loading 1.5s infinite;
}

@keyframes loading {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

/* Scrollbar personalizzata */
.table-container::-webkit-scrollbar {
  width: 8px;
}

.table-container::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb {
  background: #c1c1c1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb:hover {
  background: #a8a8a8;
}

